 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());parent=json.loads((REPO/s['source']['path']).read_text());old=np.load(REPO/parent['output']['path']);r=load_ritz(json.loads((REPO/parent['source']['path']).read_text()));e=np.load(REPO/s['equation']['path']);a=np.load(REPO/s['output']['path']);P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);V=r['V'];N=old['equality_nullspace'];cp=old['equality_particular'];x=r['before_x'];B=A@V;eq=np.isfinite(p['upper'])&(p['upper']==p['lower']);ine=~eq;rs=1/np.maximum(np.max(abs(B),axis=1),1e-15);unit=max(float(np.max(abs(r['g']))),1e-15);H=N.T@(V.T@(P@V))@N/unit;g=N.T@(V.T@(P@x+p['q'])+r['H']@cp)/unit;F=rs[ine,None]*B[ine]@N;b=rs[ine]*((A@x-p['lower'])[ine]+B[ine]@cp);z=N.T@(old['coefficients']-cp);ss=old['interior_slack'];lam=old['interior_lambda'];rd=e['H']@z+e['g']-F.T@lam;rp=F@z+b-ss;dz=e['dz'].astype(np.longdouble);dl=e['dl'].astype(np.longdouble);ds=e['ds'].astype(np.longdouble)
 # Three original first-order equations, before any slack elimination.
 r1=e['H'].astype(np.longdouble)@dz-F.T.astype(np.longdouble)@dl+e['rd'];r2=F.astype(np.longdouble)@dz-ds+e['rp'];r3=lam.astype(np.longdouble)*ds+ss.astype(np.longdouble)*dl+e['rc'];den1=max(1.,float(np.max(abs(e['rd']))),float(np.max(abs(e['H']@e['dz']))),float(np.max(abs(F.T@e['dl']))));den3=max(1.,float(np.max(abs(e['rc']))));equation_metrics=dict(stationarity_absolute=float(np.max(abs(r1))),stationarity_relative=float(np.max(abs(r1)))/den1,primal_absolute=float(np.max(abs(r2))),complementarity_absolute=float(np.max(abs(r3))),complementarity_relative=float(np.max(abs(r3)))/den3)
 checks=dict(source_hash=sha(src)==ref(src)['SHA256'],equation_hash=sha(REPO/s['equation']['path'])==s['equation']['SHA256'],all2208rows=A.shape[0]==2208,unchanged_H=np.max(abs(H-e['H']))<1e-7,unchanged_g=np.max(abs(g-e['g']))<1e-10,all_original_F=np.max(abs(F-e['F']))<1e-10,finite_gap_rhs=np.max(abs(b-e['b']))<1e-10,original_endpoint_z=np.max(abs(z-e['z']))<1e-12,saved_endpoint_s=np.array_equal(ss,e['s']),saved_endpoint_l=np.array_equal(lam,e['l']),rd_reproduced=np.max(abs(rd-e['rd']))<1e-10,rp_reproduced=np.max(abs(rp-e['rp']))<1e-10,predictor_rc=np.array_equal(ss*lam,e['rc']),newton_stationarity=equation_metrics['stationarity_relative']<1e-8,newton_primal=equation_metrics['primal_absolute']<1e-8,newton_complementarity=equation_metrics['complementarity_relative']<1e-8,no_regularization=s['physical_regularization']==0)
 controls=dict(reversed_dual_sign=float(np.max(abs(e['H']@e['dz']+F.T@e['dl']+e['rd']))),reversed_affine_rhs=float(np.max(abs(F@e['dz']-e['ds']-e['rp']))),omitted_largest_contact_row=float(np.max(abs(F[int(np.argmax(abs(e['dl'])))]*e['dl'][int(np.argmax(abs(e['dl'])))]))))
 checks.update({k:v>1e-8 for k,v in controls.items()});proposal=x+V@a['coefficients'];y=a['physical_dual'];sl=A@proposal-p['lower'];res=P@proposal+p['q']+A.T@y;obj=lambda w:float(.5*w@(P@w)+p['q']@w);pr=max(float(np.max(np.maximum(-sl[ine],0))),float(np.max(abs(sl[eq]))));gt=float((P@x+p['q'])@(proposal-x));accepted=bool(s['mode']!='equation' and pr<1e-10 and gt<0 and obj(proposal)<=obj(x)+1e-4*gt);m=dict(primal_mm=pr,stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),RootY_gamma_stationarity_N=float(abs(y[2175])),sign_N=float(np.max(np.maximum(y[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*y[ine]))),reduced_stationarity=float(np.max(abs(V.T@res))),objective_before_Nmm=obj(x),objective_proposal_Nmm=obj(proposal));qualified=accepted and all(m[k]<1e-8 for k in ['stationarity_N','gauge_N','RootY_gamma_stationarity_N','sign_N','complementarity_Nmm']);checks.update(proposal_reproduced=np.max(abs(proposal-a['proposed_x']))<1e-12,full_force_reproduced=np.max(abs(res-a['physical_residual']))<1e-8,acceptance_reproduced=accepted==bool(s['accepted_linear_steps']),physical_qualification_reproduced=qualified==s['physical_KKT_qualified'],no_nonlinear_update=s['actual_support_updates']==0);candidate=json.loads((REPO/s['candidate']['path']).read_text());checks['actual78STEP_hashes']=len(candidate['part_references'])==78 and all(sha(REPO/v['path'])==v['SHA256'] for v in candidate['part_references'].values());ok=all(checks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_AUGMENTED_INDEPENDENT_AUDIT_PASS' if ok else 'ACTUAL_P1_AUGMENTED_INDEPENDENT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},equation_metrics=equation_metrics,negative_controls=controls,metrics=m,physical_KKT_qualified=bool(qualified),accepted_linear_steps=int(accepted),actual_support_updates=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t));print(json.dumps(dict(checks=checks,equation_metrics=equation_metrics,metrics=m),default=bool));raise SystemExit(0 if ok else 2)
